/**  An account of the app, which a sign-out removes the token of */
export type Account = "gitHub" | "youTrack";

/**  Why an action can't run now, as a code with the facts its words need */
export type ActionBlocker = 
/**  A reason of the rules: its build blocked, parked, a robot that holds or lands it, a stack branch not built */
{ code: "rule"; reason: Reason } | 
/**
 *  What the next step of the subject says against its start (`NextStep::safe_push`, `dry_run`, `without_review`): the
 *  step words it
 */
{ code: "step"; blocker: StepBlocker } | 
/**  A fact of the remote it needs has no answer yet */
{ code: "pending"; fact: StepFact } | 
/**  Patronus didn't tell why the robot failed: a restart and a prompt would act as if it hadn't failed for approvals */
{ code: "problemsFailed"; message: string } | 
/**
 *  A sync rebuilds the branch, whose push waits for its build; of Push with Children, the remote statuses a running
 *  sync computes are to come. No rewrite waits for a sync: the session admits it at once, named on the table its window
 *  showed
 */
{ code: "syncing" } | 
/**
 *  A remote action on a frame nobody checked yet: the table is the frame an earlier run of the app saved
 *  (`RepositoryView::cached`), or a fact the action reads is a value of it (`FactState::Cached`). It waits for the first
 *  sync and the fresh answers of this process; a rewrite does not, the session runs it after that sync
 */
{ code: "cached" } | 
/**
 *  The operation `op` holds what it needs (a ref it pushes, a robot, a field of a pull request): of this process, it
 *  would wait for it in the queue of the session; of another process, the registry refuses it as `busy`
 */
{ code: "busy"; op: OperationId } | 
/**  The last sync didn't build the branch: `problem` the reason of its stack problem, where the sync says it */
{ code: "syncFailed"; problem: string | null } | { code: "noCommits" } | 
/**  The remote branch has every commit of the branch */
{ code: "upToDate" } | 
/**  Its open pull request is a draft: nobody is asked to review it */
{ code: "draft"; number: number } | 
/**  The robot starts from a comment on the pull request, which runs the default checks: no profile to choose */
{ code: "commentRoute"; number: number } | 
/**  Every commit of the branch has an issue reference */
{ code: "allReferenced" } | 
/**  A robot lands the branch (`reason`, its hold): it lands whatever a park says */
{ code: "parkHeld"; reason: Reason } | 
/**  Push with Children has nothing to push beyond the branch itself */
{ code: "nothingBeyond"; why: NothingBeyond } | 
/**  All of it landed: nothing is left to review in a new pull request */
{ code: "landed"; landed: Landed } | 
/**  The pull request is the user's own: GitHub takes no review of its author */
{ code: "ownPullRequest" } | 
/**  The user approved the commit the pull request shows */
{ code: "approved"; commit: string } | 
/**  The branch Patronus pushes into for the baseline is known after the first sync */
{ code: "targetUnread" } | 
/**  The baseline is no branch of origin, which Patronus pushes into */
{ code: "noTarget" } | 
/**  The pull request goes into another branch than the one Patronus pushes into: Patronus would merge it there */
{ code: "otherBase"; number: number; base: string; target: string };

/**  An action of a branch, of a whole stack or of a robot, by the id its menu item has on every surface */
export type ActionId = "safe-push" | "safe-push-with-profile" | "dry-run" | "check-approvals" | "safe-push-without-review" | "push" | "push-with-children" | 
/**  The commits someone else pushed to its remote branch, taken into the branch (`bd pick --remote`) */
"pick-remote-commits" | 
/**
 *  The copy pushed into the target where the repository lands by a push (`Intent::Land`): of a branch, of a whole
 *  stack
 */
"push-to-baseline" | 
/**
 *  The merge of its pull request on GitHub where the repository lands by one (`Intent::Land`): of a branch, of a whole
 *  stack; now ("Merge #7"), or once the checks pass ("Auto-Merge #7")
 */
"merge-pull-request" | 
/**  The auto-merge of its pull request disabled (`Intent::DisableAutoMerge`) */
"cancel-auto-merge" | "review-changes" | "open-pull-request" | "request-review" | "retarget-pull-request" | "create-pull-request" | "rename" | "move-to" | "stack-on" | "unstack" | "ungroup" | "amend-changes" | "add-issue-reference" | "squash-fixups" | "unapply" | "park" | "unpark" | "safe-push-whole-stack" | "dry-run-whole-stack" | "safe-push-main-line" | "open-stack-pull-request" | "create-stack-pull-request" | "review-whole-stack" | "restart-robot" | "push-and-restart-robot" | "cancel-robot" | "copy-robot-prompt" | "copy-robot-full-prompt" | "open-robot" | "open-robot-pull-request" | "review" | "approve" | 
/**  Approve and Safe Push, or the Safe Push alone after an approval of the head */
"safe-push-pull-request" | "request-changes" | 
/**  The branch of the table an own pull request is of */
"show-branch" | 
/**  A pull request the user added by its link leaves Reviews */
"remove-from-reviews" | 
/**  Opens where its robot would be: Patronus, or the pull request of its comment */
"open-unknown-start" | 
/**  Its record leaves the operations registry (`Intent::ForgetStart`) */
"forget-start";

/**  An action a subject offers now, and whether it can run */
export type ActionState = {
	id: ActionId,
	availability: Availability,
};

/**  What a page entry expands to, or opens */
export type ActivityDetails = 
/**  The landed report, as the island showed it */
{ type: "landed"; upstream: string; report: LandedBranch[] } | 
/**  The robot page in the Patronus web UI */
{ type: "robot"; url: string } | 
/**  A pull request on GitHub */
{ type: "pullRequest"; url: string };

/**  What a page entry is about: the chip of Activity it counts in */
export type ActivityKind = 
/**  An Update Project, applied or refused */
"update" | 
/**  A landed report a sync found after an update made elsewhere */
"landed" | 
/**  News of a Patronus robot: it merged, failed or is failing */
"patronus" | 
/**  A history rewrite with an Undo */
"rewrite" | 
/**  A review request or an approval */
"review" | 
/**  An error the page told */
"error";

/**
 *  What Activity shows, as `read_activity` read it: the journals of the recent projects, each once, and the journal of
 *  the page
 */
export type ActivityLog = {
	journals: RepositoryJournal[],
	/**  The entries of the page, of every repository, oldest first */
	page: PageEntry[],
};

export type AddIssueReferenceResult = {
	success: boolean,
	updatedCount: number,
	skippedCount: number,
	/**
	 *  Old -> new full id of every commit the reword recreated, the ones after the oldest reworded one included; empty
	 *  when nothing changed
	 */
	newCommitIds: { [key in string]: string },
	/**
	 *  HEAD after the reword, when the caller named the HEAD it expected (`RewriteOptions::expect_head`) and something
	 *  changed
	 */
	newHead: string | null,
};

/**  How the prompts the app copies run this app's bd in a repository */
export type AgentCliCommand = {
	/**
	 *  bd with `-C <repository>`, quoted for the shell, to run as written: the `bd` symlink in `~/.local/bin` when it
	 *  points at this app, else the app binary with `cli` (on Windows `bd.exe` next to it)
	 */
	command: string,
	/**  The shell is PowerShell (Windows), where a quoted path runs with `&` */
	powershell: boolean,
};

/**  What the "Install Agent CLI…" menu item installed: `bd install` (docs/guidelines/agent-cli.md) */
export type AgentCliInstall = {
	/**  The command the skills name: the `bd` symlink (macOS, Linux) or `bd.exe` next to the app (Windows) */
	bd: string,
	/**  Whether `bd` resolves to it in the user's shell */
	on_path: boolean,
	/**  The skill files written */
	skills: string[],
	/**  How agents work where a repository has no value of its own (the global git config) */
	agents: AgentRules,
};

/**  Whether the agent skill is installed (Settings → Agents) */
export type AgentCliStatus = {
	/**  The command the skills name; `null` while no skill is installed */
	bd: string | null,
	/**  The skill files that exist */
	skills: string[],
};

/**  The two rules of `bd workspace` (Settings → Agents) */
export type AgentRules = {
	/**  `branchdeck.agentLease`: in a worktree of their own, each commit landed on the user's branch */
	lease: boolean,
	/**  `branchdeck.agentSubjectBranch`: `(branch)` at the start of each subject */
	subject_branch: boolean,
};

/**  Result type for amend command that can be properly serialized by Tauri */
export type AmendCommandResult = { status: "ok"; data: AmendResult } | { status: "branchError"; data: BranchError };

export type AmendResult = {
	amendedCommitId: string,
	rebasedToCommit: string,
};

/**
 *  The error a command of the app answers, the same JSON from Tauri and from the E2E server: `{"code", "message",
 *  "details", "retry", "operation_id"}`. The page branches on `code` (and `details`), never on `message`, which is for
 *  the user
 */
export type ApiError = {
	code: ErrorCode,
	message: string,
	/**  The data of the code, typed by it; null for a code without data */
	details: ErrorDetails | null,
	/**  `code.retry()`, so the page needn't know the classes */
	retry: Retry,
	/**
	 *  The operation that failed, the `operation_id` of its log lines (the key of its Activity entry); null for an error
	 *  raised outside one
	 */
	operation_id: string | null,
};

/**
 *  `appSettings` of `settings.json`: the fields Rust reads, with their defaults, which the page takes from here (the
 *  type and `APP_SETTINGS_DEFAULTS` of the bindings, `src/stores/settings/appSettings.ts`), and the fields only the page
 *  reads, kept as they are. Deserializing is tolerant per field: a field of the wrong type
 *  or out of range is its default, so one bad field never costs the others
 */
export type AppSettings = {
	/**  General → Branch prefix: the prefix of every repository whose own git config sets none (`resolve_branch_prefix`) */
	globalUserBranchPrefix?: string | null,
	/**
	 *  Settings → Landing: the new API of Patronus (the progress of a running robot in one request, the merge profile
	 *  in the robot list); off by default
	 */
	patronusNewApi: boolean,
	/**  The zoom of the pages in every window, positive; 1 by default */
	zoom: number | null,
	/**  A focus of the main window syncs when what a sync reads changed; on by default */
	autoSyncOnFocus: boolean,
	/**  Settings → Appearance → Title bar (Windows, Linux): the system title bar and menu bar; off by default */
	systemTitleBar: boolean,
};

export type AppliedConflictFix = 
/**  The regroup is written; `result` as a move reports it, with the commits that changed */
{ kind: "applied"; result: MoveCommitsResult } | 
/**  HEAD, the issue groups or the stack parents moved since the fix was found: look for it again */
{ kind: "stale" };

/**  What an applied update did */
export type AppliedUpdate = {
	kind: UpdateKind,
	newHead: string,
	/**  Local commits replayed onto the upstream */
	replayed: number,
	/**  Local commits whose changes are already upstream: `git replay` drops a commit that becomes empty */
	droppedAlreadyUpstream: number,
};

/**  Why the approvals don't hold a Safe Push back (`domain_policy::review::skips_approvals`) */
export type ApprovalsSkip = 
/**
 *  A start through the API with a merge profile known to skip the code-owner review (its options say it), as the
 *  app's Safe Push without review starts; a `/patronus` comment has no profile
 */
"profile" | 
/**  The user said to start without them (`--without-approvals`, the app's Start Without Review) */
"withoutApprovals";

/**  A group whose approval is there, with the members Patronus counts */
export type ApprovedReviewGroup = {
	name: string,
	approvedBy: Person[],
};

/**  The parts of the archived section that changed */
export type ArchivedChanges = {
	names?: string[] | null,
	newlyArchived?: string[] | null,
	integration?: { [key in string]: BranchIntegrationInfo },
	removedIntegration?: string[],
};

/**  The archived branches: their names as the sync found them, and the integration each detection reported */
export type ArchivedSection = {
	/**  In the order the sync reported them (the page sorts them by the integration date) */
	names: string[],
	/**  The branches a sync of this session archived and that are still archived, oldest mark first */
	newlyArchived: string[],
	/**  The integration of the archived branches whose detection reported */
	integration: { [key in string]: BranchIntegrationInfo },
};

/**  The sign-ins of the app's accounts and where their tokens come from */
export type AuthStatus = {
	github: GitHubAuthStatus,
	youtrack: YouTrackAuthStatus,
};

/**  What squashing the fixups of a range does, with the HEAD it was computed for */
export type AutosquashPlan = {
	head: string,
	/**  Ordered by the target, oldest first */
	groups: PlannedGroup[],
	orphans: OrphanFixup[],
};

/**  Which planned groups a squash takes */
export type AutosquashScope = { type: "all" } | 
/**  The fixups whose target is grouped into this virtual branch */
{ type: "branch"; value: string } | 
/**  The fixups whose target is unassigned */
{ type: "unassigned" } | 
/**  Only this fixup commit, into its target */
{ type: "fixup"; value: string };

/**
 *  Whether an action can run now: disabled with the reason, never hidden for it (UX Writing, "Actions"), or what an
 *  operation of the session does to it
 */
export type Availability = { kind: "enabled" } | { kind: "disabled"; reason: ActionBlocker } | 
/**  Its intent runs in this process as the operation `op`: a start of it joins it (a spinner in place of its icon) */
{ kind: "running"; op: OperationId } | 
/**  Its intent waits in the queue of the session as the operation `op`, behind `behind`: a start of it joins it */
{ kind: "queued"; op: OperationId; behind: OperationId } | 
/**
 *  It can start, and its start waits in the queue of the session behind `op`, the newest operation of this process that
 *  holds HEAD (a rewrite, the check and the move of Update Project): a rewrite behind a rewrite
 */
{ kind: "waits"; op: OperationId };

/**  The first move of the other side after the user answered a request with a comment: the turn is the user's again */
export type BackToYou = {
	/**  Unix seconds */
	at: number,
	/**  The login of who replied (a comment or a review); None for new commits */
	repliedBy: string | null,
};

/**  The check of the checked out branch against the last fetched baseline */
export type BaselineStatus = {
	baselineBranch: string,
	/**  `None` for a local baseline, which has nothing to update from */
	update: UpdateCheck | null,
	/**  Why the check failed, e.g. a rebase in progress */
	checkError: string | null,
};

/**  A blob that the views ask for: by its id, and for a file of the working tree, by its path too */
export type BlobRequest = {
	id: string,
	/**  The path of the file in the working tree, relative to the repository, when the id is of a working tree file */
	path: string | null,
};

/**  The text of a blob */
export type BlobText = 
/**  The bytes as UTF-8, an invalid sequence replaced with U+FFFD */
{ kind: "text"; id: string; text: string } | { kind: "binary"; id: string } | 
/**  Over `MAX_BLOB_BYTES` */
{ kind: "tooLarge"; id: string; size: number } | 
/**  No blob of the repository and no file of the working tree has the id */
{ kind: "missing"; id: string };

/**  How a view draws a block */
export type BlockKind = 
/**  A change */
"changed" | 
/**
 *  The lines are equal under the policy, an empty list of inner changes (whitespace only, or a blank line under
 *  `Ignore`): drawn pale, still a change that counts and that the navigation stops at, as in IntelliJ
 */
"whitespaceOnly" | 
/**
 *  `IgnoreBlankLines` cut the block off the ends of a run of changes, where IntelliJ drops it: drawn as unchanged,
 *  not counted, and the change navigation skips it. A view needs it to align the two sides.
 */
"ignored";

/**  Why a branch is not rebuilt: its parent can't be built on */
export type BlockReason = 
/**  The parent can't be placed: a stack problem */
"Problem" | 
/**  The parent failed to build */
"Error" | 
/**  A commit of the parent has a merge conflict */
"Conflict" | 
/**  The parent is blocked itself */
"Blocked";

/**  The parts of one branch that changed */
export type BranchChange = {
	head?: BranchHead | null,
	commits?: Commit[] | null,
	sync?: BranchSync | null,
	copies?: CommitSync[] | null,
	remote?: BranchRemote | null,
	structure?: BranchStructure | null,
};

/**  Branch operation errors. */
export type BranchError = ({ Generic: string }) & { MergeConflict?: never } | ({ MergeConflict: MergeConflictInfo }) & { Generic?: never };

/**  What the grouping says of a branch; a field without a value is absent */
export type BranchHead = {
	name: string,
	latestCommitTime: number,
	summary: string,
	/**  The title of the branch's description (`bd describe`); `None` without one */
	descriptionTitle?: string | null,
	/**
	 *  `description_title` split at the issue key it starts with, which a row that shows the key leaves out
	 *  (`sync_utils::issue_pattern::issue_lead`)
	 */
	descriptionLead?: IssueLead | null,
	/**  The issue key the name starts with (`IJPL-1` of `IJPL-1` and of `IJPL-1-cache`), which the row shows in the name */
	nameIssueKey?: string | null,
	allCommitsHaveIssueReferences: boolean,
	/**  Most frequent author email in this branch's commits */
	myEmail?: string | null,
	origin: BranchOrigin,
	/**  The issue the branch belongs to */
	issueKey?: string | null,
	/**  Where the branch sits in its stack; `None` without stacked branches */
	stack?: BranchStack | null,
};

/**  Unified branch integration info */
export type BranchIntegrationInfo = {
	name: string,
	summary: string,
	status: BranchIntegrationStatus,
};

/**  Unified branch integration status */
export type BranchIntegrationStatus = { kind: "integrated"; integratedAt: number | null; confidence: IntegrationConfidence; commitCount: number; 
/**
 *  The baseline commit that brought the branch in: the merge, the newest equivalent commit or the squash; `None`
 *  when it can't be found, and in cache notes written before it was recorded
 */
commit: UpstreamCommit | null } | { kind: "notIntegrated"; totalCommitCount: number; integratedCount: number; orphanedCount: number; integratedAt: number | null } | { kind: "partial"; missing: number };

/**  What the rules decide of a branch over its Patronus facts (`domain_policy::holds`, `domain_policy::land`) */
export type BranchLanding = {
	/**  What refuses its push (`holds::branch_hold`) */
	hold: HoldView | null,
	/**  Why a Safe Push can't start (`land::start_refusal`) */
	start: Reason | null,
	/**  Why a Dry Run can't start: a robot on the last commit, else the hold of the push it makes */
	dryRun: Reason | null,
	/**  The running robot a Safe Push start replaces, by id: its own, on an older commit, which the push cancels first */
	replaces: string | null,
	/**
	 *  Why the push an action needs (a pull request, a review request, a start) can't be made for the user
	 *  (`holds::push_blocker`)
	 */
	push: Reason | null,
};

/**  The check of a typed branch name: what it is, and the name the branch gets (`sanitized`) */
export type BranchNameCheck = {
	state: BranchNameState,
	/**  The name trimmed, its runs of whitespace turned into `-` */
	sanitized: string,
};

/**  What a typed branch name may be */
export type BranchNameRules = {
	/**  Stacked branches are on: a `/` separates a parent from its branch */
	stacks?: boolean,
	/**  Only a branch name, not `parent/branch` (with stacked branches on: a rename) */
	leafOnly?: boolean,
};

/**  What a typed branch name is; the page words each (`src/presenters/branch-name.ts`) */
export type BranchNameState = 
/**  Nothing typed yet */
"empty" | "valid" | 
/**  Under two characters */
"tooShort" | 
/**  A character other than a letter, a digit, `-`, `_`, `.`, `/` or a space, or a leading `.` */
"invalidChars" | 
/**  A `/` in a name that names only a branch (`BranchNameRules::leaf_only`) */
"leafOnly" | 
/**
 *  The grouping would rename it (`sanitize_branch_name`: `-`, `.` or `/` at an end, `--`), or it has `..` or `//`,
 *  so the virtual branch would not get this name
 */
"invalidRef";

/**  What a request for branch names ended with; a failure of git or of `claude` is an outcome, not an error */
export type BranchNameSuggestionOutcome = 
/**  One or two distinct names, the best first */
{ status: "suggested"; names: string[] } | 
/**  A newer request for this window replaced it: `claude` was killed */
{ status: "superseded" } | 
/**  The `claude` CLI is not installed */
{ status: "claudeMissing" } | 
/**  `claude` is not logged in (`claude`, then `/login`) */
{ status: "notLoggedIn" } | 
/**  git or `claude` failed, e.g. offline, overloaded or timed out */
{ status: "error"; message: string };

/**  What groups the commits of a branch */
export type BranchOrigin = 
/**  An explicit `(name)` subject prefix */
"Prefix" | 
/**  The issue key of the subjects (`ABC-123: ...`), no explicit prefix */
"Issue" | 
/**
 *  The issue groups (`refs/branch-deck/issue-groups`) put the commits of other issue keys into the branch; no
 *  explicit prefix
 */
"IssueGroup";

/**  The Patronus facts of one branch; a branch with none is not listed */
export type BranchPatronus = {
	/**
	 *  The robot of the branch (`domain_policy::robot_match`: started on it, or of a temporary ref at its local or remote
	 *  tip), by id: the robot of its row
	 */
	robotId: string | null,
	landedBy: LandedByView | null,
	span: SpanView | null,
	/**
	 *  The nearest ancestor whose robot runs, or that a running robot of a side branch lands: a Safe Push of the branch
	 *  would land its commits a second time
	 */
	landingAncestor: RobotOf | null,
	/**
	 *  What its Safe Push needs of a branch outside what it lands; a missing declaration names the running Safe Push of
	 *  the branch that adds the name (`landingIn`)
	 */
	landingNeeds: LandingNeeds,
	/**  What the rules decide of the branch over these facts */
	landing: BranchLanding,
};

/**
 *  What the pushes of a branch send besides the branch, root first, as `domain_policy::push::push_plan` orders them over
 *  the table and the holds of the robots: the branch goes last in each, and an empty list sends it alone. A list absent
 *  is the one of its structure, most of the time: the view sends only what differs (`RepositoryView::pushes`)
 */
export type BranchPush = {
	/**
	 *  Push Stack: the branches it is built on that have work for the remote, root first, up to the nearest one a running
	 *  Safe Push holds; one a merged Safe Push landed whole, or the fetched baseline has whole, is left out. Absent while
	 *  it is every branch it is built on (`BranchStructure::ancestors`)
	 */
	stack?: string[] | null,
	/**
	 *  The push of the push button and of an action that needs the branch on the remote (a pull request, a review
	 *  request): as `stack`, starting above the nearest branch whose push drops remote commits, which asks first in its
	 *  row; absent while none of `stack` asks first (`stack` then). A Safe Push start pushes what its decision does (the
	 *  `Push` effect, `domain_policy::push::start_push`)
	 */
	action?: string[] | null,
	/**  The push button pushes the stack, `action` and then the branch: the branch has work for the remote and asks nothing */
	button?: boolean,
	/**  Push with Children; absent for a branch nothing but parked branches is stacked on */
	children?: ChildrenPush | null,
	/**
	 *  Push Up to Here of the commits of the branch the remote lacks; absent while every one of them offers it, it sends
	 *  the branches of Push Stack first (`stack`) and nothing stops it
	 */
	upTo?: PushUpTo | null,
};

/**  What the remote has of a branch */
export type BranchRemote = {
	/**  The last remote status a sync computed; `None` until one did, kept while the branch is rebuilt */
	status: RemoteStatusUpdate | null,
};

export type BranchReview = {
	/**  In the order of the chain: the root first */
	segments: BranchReviewSegment[],
};

/**  The part of a stack a review of a branch shows first */
export type BranchReviewPart = 
/**  The branch on its parent */
"own" | 
/**  The stack from the baseline */
"all";

/**  A branch of the chain: its commits on top of its parent (the baseline for the root) */
export type BranchReviewSegment = {
	name: string,
	/**  The head of the parent, or the commit the root is built on */
	base: string,
	head: string,
	/**  Newest first; the commits of a pull request are of the same type, a review shows both alike */
	commits: ReviewCommit[],
};

/**
 *  What the rules of a branch do to the pull requests into it and to a push into it (`remote_facts::branch_rules`): a
 *  fact of the session for the bases of the open pull requests someone approved, which the Safe Push popover and the
 *  Request Review form read before a push takes the approvals away, and for the target of the baseline while the
 *  repository lands by a push (`domain_policy::landing_route`)
 */
export type BranchRules = {
	/**  A push of new commits dismisses the approvals of a pull request into the branch */
	dismissStaleReviewsOnPush: boolean,
	/**  A change reaches the branch only through a pull request (the rule `pull_request`) */
	requiresPullRequest?: boolean,
	/**  Every commit pushed into the branch is signed (`required_signatures`) */
	requiresSignatures?: boolean,
	/**  Status checks pass before a change reaches the branch (`required_status_checks`) */
	requiredStatusChecks?: boolean,
	/**  A change reaches the branch only through the merge queue (`merge_queue`) */
	mergeQueue?: boolean,
	/**  Only the users the ruleset lets bypass it update the branch (`update`) */
	restrictsUpdates?: boolean,
};

/**  The table a branch is a row of: the main one, or the Parked card of the branches kept local */
export type BranchSection = "main" | "parked";

/**  Where a virtual branch sits in its stack; sent only with stacked branches on */
export type BranchStack = {
	declaredParent: string | null,
	/**  Where `declared_parent` comes from */
	parentSource: ParentSource | null,
	parentState: ParentState | null,
	/**  The branch the virtual branch is built on; `None` for the baseline */
	effectiveBase: string | null,
	/**
	 *  Why the branch is not rebuilt this sync, known before the sync starts: its parent can't be built (a problem, a
	 *  conflict, a failure or a block); a parent that fails while building blocks its descendants with a `Blocked`
	 *  branch status
	 */
	blockedBy: StackBlock | null,
	/**  Why the branch itself can't be placed, each with its fixes; it is not rebuilt either */
	problems: StackProblemView[],
	/**
	 *  The declared parent has no commits, so the branch is built on its nearest active ancestor or the baseline and the
	 *  base of its pull request differs from the declared parent
	 */
	prBaseChanged: boolean,
	/**  A commit of the branch comes before every commit of its parent on the current branch */
	childPrecedesParent: boolean,
};

/**  The status of a branch in the table: `Syncing` until the sync reports how it ended */
export type BranchStatus = "Syncing" | "Created" | "Updated" | "Unchanged" | "Error" | "MergeConflict" | "AnalyzingConflict" | "Blocked";

/**
 *  Where a branch is among the branches of the table, as the rules of `domain_policy::stack` and `domain_policy::parked`
 *  decide it for the app and `bd` alike (`repository_model::derive`)
 */
export type BranchStructure = {
	/**  The branch of the table it stacks on, its declared parent; absent for a root or a parent the table lacks */
	parent?: string | null,
	/**  The branches stacked directly on it, in the order of the table */
	children?: string[],
	/**  The branches it is built on, root first: the chain of its effective bases among the branches of the table */
	ancestors?: string[],
	/**  The branches stacked on it, directly or further down, each after its parent */
	descendants?: string[],
	/**
	 *  The main line of its stack below it: at each fork the child with the longest chain (lane 0 of the stack graph),
	 *  empty when nothing is stacked on it. A Safe Push of its last branch lands the branch and the line in one robot
	 */
	mainLine?: string[],
	/**  Why it stays local: its own line of the parked branches, or a parked branch it is built on; absent otherwise */
	parked?: Parked | null,
	/**
	 *  Of the root of a stack that forks: the first member of its stack branch that is parked, which keeps the stack
	 *  branch local; absent otherwise
	 */
	stackParked?: ParkedMember | null,
	/**
	 *  Of the root of a stack: its whole stack, which one Safe Push lands (`domain_policy::stack::whole_stack_of`, by
	 *  declared parent); absent for a branch alone and for a branch that heads no stack
	 */
	wholeStack?: WholeStackView | null,
	/**  The table it is a row of, in the order of the table (`RepositoryView::order`); absent for the main one */
	section?: BranchSection,
};

/**  What the sync made of a branch */
export type BranchSync = {
	status: BranchStatus,
	/**  The commits the sync reported while the branch was `Syncing` (the progress of its row) */
	processedCount: number,
	hasError: boolean,
	/**  The error of the branch or of its last failed commit */
	errorDetails?: BranchError | null,
	/**  Why a `Blocked` branch was not rebuilt (its parent can't be built on); `None` otherwise */
	blockedReason?: string | null,
};

/**  A branch of the table, in the parts that change for different reasons */
export type BranchView = {
	head: BranchHead,
	/**  Newest first, as the sync grouped them; they change only with a grouping */
	commits: Commit[],
	sync: BranchSync,
	/**  What the sync made of each commit, in the order of `commits` */
	copies: CommitSync[],
	remote: BranchRemote,
	/**
	 *  Where the branch is among the others: its stack and whether it is parked; it changes only with a grouping (and,
	 *  of the root of a whole stack, with its stack branch)
	 */
	structure: BranchStructure,
};

/**  Result of browsing for a repository */
export type BrowseResult = {
	path: string | null,
	valid: boolean,
	error: string | null,
};

/**  A problem TeamCity reports for a build, e.g. a compilation error */
export type BuildProblem = {
	/**  e.g. `TC_COMPILATION_ERROR`, `TC_EXIT_CODE`, `TC_FAILED_TESTS` */
	kind: string | null,
	/**  Cut to the limit */
	details: string,
};

/**
 *  What the start of the app hands the page of the main window before it subscribes (`window.__BD_MODEL__`,
 *  `src-tauri/src/warm_start.rs`): the project the view is of and the seed of its session, the view of the frame an
 *  earlier run saved
 */
export type CachedModel = {
	repositoryPath: string,
	view: RepositoryView,
};

/**
 *  What a window asks to stop (`cancel_operation`): an operation of this process that waits for the repository lock, or
 *  whose next effect has not started
 */
export type CancelOperationParams = {
	op: OperationId,
};

/**
 *  The commits of a branch a running robot's commit has (`BranchSpan`): ids of the checked-out branch, newest first,
 *  and those of them it has in an earlier version
 */
export type Carried = {
	commits: string[],
	amended: string[],
};

export type CheckCount = {
	name: string,
	count: number,
	/**  The page of the newest robot it failed */
	robot_url: string,
};

export type ChecksState = "passing" | "failing" | "pending";

/**  The checks of the head commit, summarized */
export type ChecksSummary = {
	/**  Failing if any check failed, else pending if any is still running, else passing */
	state: ChecksState,
	passed: number,
	failed: number,
	pending: number,
	/**  The names of the failed checks, at most a few */
	failedNames: string[],
};

/**  What Push with Children of a branch sends, in one atomic push, parents first */
export type ChildrenPush = {
	/**
	 *  The branch while it has work for the remote, then the branches stacked on it that have work, each after its
	 *  parent: none parked, none a Safe Push holds or a merged one landed, none whose push drops remote commits. Absent
	 *  while it is the branch and every branch stacked on it (`BranchStructure::descendants`)
	 */
	order?: string[] | null,
	/**  The branches stacked on it whose push drops remote commits they lack: left out, each asks first in its row */
	askFirst?: string[],
	/**  Of the root of a stack that forks: what the push does with the stack branch of the whole stack */
	stackBranch?: StackBranchAlong | null,
	/**  It pushes more than the branch itself: a branch stacked on it, or the stack branch along */
	offers?: boolean,
};

/**  The parameters of `clear_activity` */
export type ClearActivityParams = {
	/**  The recent project whose log goes: the journal of its repository and the page entries of it */
	repositoryPath: string,
};

/**  A CLI that agents and the app use */
export type CliTool = 
/**  JetBrains/teamcity-cli: the logs and tests of the builds of a robot */
"teamcity" | 
/**  JetBrains/youtrack-cli: the issues of the commits */
"youtrack";

/**  The one thing a row offers next, decided in Rust; the skill has a line of its own */
export type CliToolAction = "install" | 
/**  The CLI is signed in to no server */
"signIn" | 
/**  A newer release than the installed one */
"update" | 
/**  The agents get the skill the CLI bundles */
"installSkill" | 
/**  The agents have an older skill than the one the CLI bundles */
"updateSkill" | 
/**  The agents lose the skill */
"removeSkill";

/**  What an action did, in the words of its toast */
export type CliToolActionDone = {
	title: string,
	/**  Why the skill an install or an update brings along failed, while the CLI itself is done */
	skill_problem: string | null,
};

/**  A line of the output of a running action, or the page a sign-in opened in the browser */
export type CliToolProgress = {
	line: string,
	/**  The authorize page of a sign-in, for "Open in Browser" when the browser didn't come up */
	url: string | null,
};

/**  A server the CLI is configured for */
export type CliToolServer = {
	/**  e.g. `https://buildserver.labs.intellij.net`, without a trailing `/` */
	url: string,
	/**  The login the token belongs to */
	user: string | null,
	state: CliToolSignInState,
	/**  Why `state` is `Failed`, in the CLI's words */
	error: string | null,
	/**  Unix seconds when the token expires; None for a token without an expiry (a permanent one) */
	expiresAt: number | null,
};

/**  How a CLI is signed in to one server */
export type CliToolSignInState = "authenticated" | 
/**  TeamCity's guest access: read-only, no token */
"guest" | 
/**  The CLI has the server but its token is missing, rejected or unreadable */
"failed";

/**  The agent skill a CLI bundles (`teamcity skill`, `youtrack skill`) */
export type CliToolSkill = {
	/**  e.g. `teamcity-cli` */
	name: string,
	/**  The `version:` of the installed `SKILL.md`; None while it is not installed */
	installed: string | null,
	/**  The version this release of the CLI installs */
	bundled: string | null,
	/**
	 *  What the line of the skill offers besides Remove: `InstallSkill` while the agents have none, `UpdateSkill` while
	 *  theirs is older than the bundled one
	 */
	action: CliToolAction | null,
};

/**  A CLI as Settings → Tools shows it */
export type CliToolStatus = {
	tool: CliTool,
	/**  The binary found, e.g. `/opt/homebrew/bin/teamcity`; None while it is not installed */
	binary: string | null,
	/**  e.g. `1.6.0`; None when it is not installed or does not tell */
	version: string | null,
	servers: CliToolServer[],
	/**  The skill the CLI bundles for the agents; without the CLI, the one the agents may have of an earlier install */
	skill: CliToolSkill | null,
	/**  The newest release, once known; None before the first check or offline */
	latest: string | null,
	/**  The manager the app installs and updates it with; None when the machine has none the CLI is packaged for */
	manager: PackageManager | null,
	action: CliToolAction | null,
	/**
	 *  The command of `action` for a terminal, while the app can't run it itself (no package manager, a sign-in it
	 *  doesn't start); None when the app runs it
	 */
	command: string | null,
	/**  Why a part could not be read (the CLI timed out, answered what the app can't parse), in a sentence */
	problem: string | null,
	/**
	 *  The YouTrack of the app's own sign-in, for a `youtrack` signed in to none: Use Branch Deck Sign-In hands it a token
	 *  of it; None for `teamcity`, or when the app is signed in to no YouTrack
	 */
	signInWith: string | null,
};

/**  Struct to hold commit data returned by git CLI */
export type Commit = {
	originalHash: string,
	strippedSubject: string,
	message: string,
	author: string,
	authorTime: number,
	committerTime: number,
	/**
	 *  `subject` as the grouping reads it (`sync_utils::commit_subject::subject_parts`), for the page that shows and words
	 *  it; the commit list writes it with `subject`
	 */
	subjectParts: SubjectParts,
};

/**  A block of a commit body */
export type CommitBodyBlock = 
/**
 *  Prose, a line per line it reads as: hard-wrapped lines joined by a space; a line after a hard break (two spaces,
 *  `\`), a quote line and a table row each a line of their own, a heading and a rule a paragraph of their own
 */
{ type: "paragraph"; lines: string[] } | 
/**
 *  A bullet (`-`, `*`, `+`, `•`) or numbered (`1.`, `1)`) list: the items without their markers, their wrapped and
 *  indented lines joined, nested items flattened
 */
{ type: "list"; ordered: boolean; 
/**  The number of the first item of an ordered list */
start: number; items: string[] } | 
/**
 *  Code or other text whose line breaks and spacing matter (fenced, or indented by four spaces or a tab), verbatim
 *  without the common indent and the fences
 */
{ type: "preformatted"; text: string } | 
/**
 *  The `Token: value` lines that end the message (`Co-Authored-By:`, `Signed-off-by:`, `Fixes:`…), an indented line
 *  joined to its trailer
 */
{ type: "trailers"; lines: string[] };

/**  The parameters of `commit_body_blocks` */
export type CommitBodyParams = {
	/**  The whole message: its body is the lines after the subject line */
	message: string,
};

/**  A changed file of a commit */
export type CommitFile = {
	/**  The path after the commit */
	path: string,
	status: FileStatus,
	/**  The path before a rename or copy */
	oldPath: string | null,
	/**  Added lines; 0 for a binary file */
	additions: number,
	/**  Deleted lines; 0 for a binary file */
	deletions: number,
	/**  Git counts no lines for the file (`-` in `--numstat`) */
	binary: boolean,
	/**  The blob id before the commit, the commit of a submodule; `None` for an added file */
	oldId: string | null,
	/**  The blob id after the commit, the commit of a submodule; `None` for a deleted file */
	newId: string | null,
	/**  A side is a submodule (mode 160000): its id is the commit the submodule points to */
	submodule: boolean,
};

/**  The changed files of a commit against its first parent (or of a range), with the sums of their line counts */
export type CommitFiles = {
	/**  The commit id, or `<base>..<head>` for a range (`DiffSubject::id`) */
	commitId: string,
	/**  In git's order: by path */
	files: CommitFile[],
	additions: number,
	deletions: number,
};

/**
 *  The branch a commit message groups into (`history_rewrite::commit_grouper::group_of`), as the forms that type a
 *  message or a branch name preview it (`preview_group`)
 */
export type CommitGroup = {
	/**  The branch; with stacked branches the leaf of `(parent/leaf)` */
	branch: string,
	origin: GroupOrigin,
	/**
	 *  With stacked branches: the parent the prefix declares, else the stack parent of the branch; `None` for none and
	 *  without stacked branches
	 */
	parent: string | null,
	/**  With stacked branches and a parent: where it comes from */
	parentSource: ParentSource | null,
	/**  With stacked branches: the prefix has an empty level (`(a//b)`), so the branch reports an error */
	invalid: boolean,
};

/**
 *  Simple commit information with hash and message.
 *  Used for passing commit data between frontend and backend.
 */
export type CommitInfo = {
	hash: string,
	message: string,
};

/**  A commit ahead of the baseline (abbreviated ids are fine) and its new text */
export type CommitReword = {
	commit: string,
	text: RewordText,
};

/**  What the sync made of a commit: its virtual copy; the fields are absent until the sync reported the commit */
export type CommitSync = {
	/**  The virtual copy the sync wrote or kept */
	hash?: string | null,
	status?: CommitSyncStatus | null,
	error?: BranchError | null,
	/**  The conflict of git that the copy resolved by words (`branchdeck.resolveByWords`) */
	resolved?: WordResolutionSummary | null,
};

/**  Status of a commit synchronization. */
export type CommitSyncStatus = "Pending" | "Created" | "Unchanged" | "Error" | "Blocked";

/**  The config file an entry comes from, in git's order: a later scope wins over an earlier one */
export type ConfigScope = "system" | "global" | 
/**  `.git/config` of the repository, shared by its linked worktrees: the only one Branch Deck writes */
"local" | 
/**  `config.worktree` of one worktree (`extensions.worktreeConfig`) */
"worktree" | 
/**  `git -c` or `GIT_CONFIG_*` of the process; also a scope git names `unknown` */
"command";

/**  A key as git resolves it */
export type ConfigSetting<T> = {
	/**  The effective value; the default when no config sets the key or its value is invalid (the set text for a string) */
	value: T,
	/**  The scope of the effective entry; None when the default applies */
	scope: ConfigScope | null,
	/**  The local config sets the key, so unsetting it there changes something */
	localSet: boolean,
	/**  Why the effective value is not taken, as git or Branch Deck would refuse it */
	invalid: string | null,
	/**  The value once the local config no longer sets the key: the last system or global entry, else the default */
	fallbackValue: T,
	/**  The scope of `fallback_value`; None for the default */
	fallbackScope: ConfigScope | null,
};

/**  What the user accepts before a start (the contract's `Confirmation`) */
export type Confirmation = 
/**
 *  It lands `count` branches it is built on with the branch, more than its row; of a whole stack the branches of it
 *  besides its root
 */
{ kind: "landsMoreThanRow"; count: number } | 
/**  It starts with a profile, not the default checks: the last robot's or one chosen */
{ kind: "nonDefaultProfile"; id: string } | 
/**  It cancels the running Safe Push of an older commit it replaces (`LandingAllowances::cancel_running` in `bd`) */
{ kind: "cancelsRobot"; robotId: string } | 
/**
 *  Patronus judges the approvals only when the robot starts: it doesn't evaluate the pull request, or GitHub didn't
 *  list the pull requests, so the start is not known
 */
{ kind: "approvalsJudgedAtStart" } | 
/**
 *  Patronus couldn't answer the code-owner review (`message`, its pre-check failed): the robot checks the approvals
 *  when it starts (`LandingAllowances::allow_unknown_review` in `bd`, D14)
 */
{ kind: "reviewUnknown"; message: string } | 
/**  The push dismisses the approvals of pull request `number`, none of which Patronus counts */
{ kind: "dismissesApprovals"; number: number } | 
/**
 *  GitHub didn't answer the rules of the target: whether the push keeps the approvals of pull request `number` is not
 *  known (`LandingAllowances::allow_unknown_rules` in `bd`)
 */
{ kind: "rulesUnknown"; number: number } | 
/**  It starts without the approvals the code owners haven't given (a Safe Push without review) */
{ kind: "withoutApprovals" } | 
/**  It lands a piece of a stack whose pull request `number` is open: those approvals count for the whole stack only */
{ kind: "stackPullRequestApprovalsDontCount"; number: number } | 
/**
 *  Its push replaces `commits` commits of the remote branch of `branch` the branch lacks, someone's work (allowed by
 *  `LandingAllowances::allow_force`, D12)
 */
{ kind: "forcePushDrops"; branch: string; commits: number } | 
/**
 *  A push of the copy into the target runs no CI: the checks did not pass on the commit it lands (`why`;
 *  `LandingAllowances::allow_without_checks` in `bd`)
 */
{ kind: "unchecked"; why: Unchecked } | 
/**
 *  `by` requested changes on its open pull request `number` (GitHub's decision when `by` is empty), which a push into
 *  the target lands past (`LandingAllowances::allow_without_checks` in `bd`)
 */
{ kind: "changesRequested"; number: number; by: string[] } | 
/**
 *  What the gate of the route asks (`domain_policy::landing_route`): a rule of the target the user may bypass, the
 *  status checks a push lands without, a refusal of the server before (`LandingAllowances::bypass_rules` in `bd`)
 */
{ kind: "routeRule"; reason: Reason } | 
/**
 *  Checks of the open pull request `number` that the rules of its base don't require fail or still run
 *  (`mergeStateStatus` `UNSTABLE`): GitHub merges it all the same (`LandingAllowances::allow_without_checks` in `bd`)
 */
{ kind: "checksNotRequired"; number: number } | 
/**
 *  The repository allows only squash merges: the commit GitHub writes pairs with no original, so the update after it
 *  may stop on a conflict of the originals
 */
{ kind: "squashOnly"; number: number };

/**  Analysis results for a merge conflict, including missing commits and divergence information. */
export type ConflictAnalysis = {
	missingCommits: MissingCommit[],
	mergeBaseHash: string,
	mergeBaseSubject: string,
	mergeBaseMessage: string,
	mergeBaseTime: number,
	mergeBaseAuthor: string,
	divergenceSummary: DivergenceSummary,
};

/**  A commit involved in a merge conflict: the applied commit, its original parent, the target, or one referenced in conflict markers */
export type ConflictCommit = {
	hash: string,
	message: string,
	author: string,
	authorTime: number,
	committerTime: number,
	/**  The parts of the subject the page shows (`Commit::subject_parts`) */
	subjectParts: SubjectParts,
};

/**  A conflicting file of a cherry-pick, as a conflict is reported: what the view lists before it reads the contents */
export type ConflictFile = {
	file: string,
	/**
	 *  The conflicts of the merged file, its `<<<<<<<` marker lines (`count_conflicts`); 0 when one side deleted the
	 *  file and the other changed it (a modify/delete conflict)
	 */
	conflictCount: number,
};

export type ConflictFix = {
	/**  The HEAD the fix is for */
	head: string,
	/**
	 *  What the fix was found for: HEAD, the issue groups, the stack parents and the oldest commit ahead of the
	 *  baseline (`fingerprint`); an apply refuses another one
	 */
	fingerprint: string,
	components: FixComponent[],
	/**  The branches that still conflict or have a dangling reference afterwards */
	unresolved: string[],
	search: SearchState,
	trials: number,
};

/**
 *  A commit copied onto HEAD by a reapply or a pick of remote commits: the commit it was copied from, its copy and the
 *  subject of the copy
 */
export type CopiedCommit = {
	/**  The commit of the unapplied branch (or of its restored chain), or of the remote branch */
	commit: string,
	/**  Its copy on HEAD (a dry run of a reapply: the one it writes) */
	newId: string,
	/**  The subject of the copy; of a pick with the prefix of the branch */
	subject: string,
};

/**  What the numbers miss */
export type Coverage = {
	/**  The robots of the window that count, everyone's */
	robots: number,
	/**  The user's finished robots of the runs window whose checks are not read yet: the next read asks for them */
	runs_missing: number,
	/**  The weeks Patronus did not list */
	weeks_missing: number,
};

/**  A pull request to open for a subject: of its virtual branch into the target, of the stack branch of a whole stack */
export type CreatePullRequest = {
	subject: Subject,
	title: string,
	body: string,
	/**  The user of the token is its assignee ("Assign to me") */
	assignSelf: boolean,
	/**  Logins; the author's own is left out, GitHub refuses it */
	reviewers: string[],
	/**
	 *  "Continue on GitHub": the user opens it in GitHub's form, which shows nothing of a branch GitHub doesn't have yet;
	 *  the plan pushes what it needs and waits until GitHub has the branch (`PlannedEffect::WaitForMirror`), and the page
	 *  opens the form
	 */
	onGitHub?: boolean,
};

/**  A pull request the app or `bd` opened, or found open */
export type CreatedPullRequest = {
	/**  Its reviewers are the ones requested */
	pullRequest: PullRequest,
	/**  False for a pull request that already existed: nothing of the request was applied to it */
	created: boolean,
	/**  The logins GitHub assigned */
	assignees: string[],
	/**  What failed after the pull request was created, e.g. "cannot request review from bob: …" */
	warnings: string[],
};

/**  Where the name is: a side of a file of the review, a line from 0 and a UTF-16 column */
export type DeclarationSite = {
	/**  The path of the side: the old path for the old side of a rename */
	path: string,
	side: DiffSide,
	blob: BlobRequest,
	line: number,
	column: number,
};

/**  A declaration in a side of a file of the review */
export type DeclarationTarget = {
	path: string,
	side: DiffSide,
	/**  The line of the declared name, from 0, and its UTF-16 columns */
	line: number,
	column: number,
	endColumn: number,
	/**  What is declared: `class`, `function`, `property`, `constant`, `enumEntry`, `typeAlias`, `module`, `macro`, `local` */
	kind: string,
	/**  The name of the declaration it is a member of */
	container: string | null,
	/**  A file outside the review (found by `accio`); none for a file of the review */
	outside: OutsideFile | null,
};

/**  A parent and the commits that declare it */
export type DeclaredParent = {
	parent: string,
	commits: string[],
};

/**  The robots of one owner or of the user */
export type Delivery = {
	merged: number,
	failed: number,
	canceled: number,
	/**  Finished robots per merge; null without a merge */
	robots_per_merge: number | null,
	/**  From the start to the merge of a merged robot, seconds */
	merge_time: Spread | null,
	/**  The weeks of the window from the oldest, by the local Monday a robot finished in */
	weeks: WeekCount[],
	/**  Dry runs, which land nothing: counted apart */
	dry_runs: number,
	/**  Emergency robots, which skip checks: counted apart */
	emergency: number,
};

/**
 *  What a window shows and needs of a session (docs/design/rust-domain-authority.md, "Demand"), the one thing the page
 *  tells of itself: the facts it asks for, and how often. The session keeps the demand of each window by its
 *  subscription and asks for the facts of all of them; the lists name branches by name, robots by id
 */
export type Demand = {
	/**  The window has the focus */
	focused: boolean,
	/**  The machine is online (`navigator.onLine`): offline, no poll asks */
	online: boolean,
	/**
	 *  The branches whose rows the window shows with a step that waits for the review readiness (the page's rule of a
	 *  step until the next step is decided in Rust)
	 */
	visibleBranches: string[],
	/**  The whole stacks whose island headers the window shows with such a step, by root */
	visibleStacks: string[],
	/**
	 *  The subjects a surface needs a fact of now, asked at once beside whatever is in flight (the Safe Push popover and
	 *  its click, the "Create pull request" dialog): a branch by name, the whole stack of a root as `stack:<root>`
	 *  (`stack_readiness_key`)
	 */
	needed: string[],
	/**  The robots whose details a surface shows (the robot popover, the preview, a row of the landing overview) */
	robotDetails: string[],
	/**
	 *  The robots of no branch the window started and follows until they finish (the Safe Push of a reviewed pull
	 *  request): polled with the robots of the branches
	 */
	watchedRobots: string[],
	/**  The window shows the Reviews view: the review requests are read with the rest of Reviews */
	reviews?: boolean,
	/**
	 *  The pull requests the review windows of the window show: their actions stay in the view while a window shows them,
	 *  also once no listing has them any more
	 */
	reviewWindows?: number[],
};

/**  The GitHub repository found without `branchdeck.githubRepository` */
export type DetectedGitHubRepository = {
	/**  `owner/name` */
	fullName: string,
	source: GitHubRepositorySource,
};

/**  A block of changed lines */
export type DiffBlock = {
	/**  0-based line indices, the end exclusive; `start == end` is a side without lines */
	oldStart: number,
	oldEnd: number,
	newStart: number,
	newEnd: number,
	kind: BlockKind,
	/**  The sides have the same number of lines and each pair is similar: the Inline view may draw pair i as one row */
	inlinePairs: boolean,
	/**
	 *  For each line of the old side, `[start, end, kind, start, end, kind, ...]`: UTF-16 offsets inside the line, the
	 *  end exclusive, never the line end, and the `RangeKind` of the inner change, as IntelliJ types a fragment.
	 *  `start == end` marks the empty side of an inserted or a deleted change, which a view draws as a thin bar. Empty
	 *  when the block has no inner ranges: `Ignored`, `WhitespaceOnly`, ranges dropped, or `line_level_only`.
	 */
	oldRanges: number[][],
	newRanges: number[][],
};

/**  What the views show of a file */
export type DiffContent = {
	kind: "text",
} & TextDiff | 
/**  A side is binary: a NUL in its first 8000 bytes, or git counts no lines */
({ kind: "binary" }) & { newBytes?: never; newCommit?: never; oldBytes?: never; oldCommit?: never } | 
/**  A side is over `MAX_BLOB_BYTES`; the sizes in bytes, 0 for a missing side */
({ kind: "tooLarge"; oldBytes: number; newBytes: number }) & { newCommit?: never; oldCommit?: never } | 
/**
 *  A submodule: the commit it points to on each side, `None` for a side without it, as git writes
 *  `Subproject commit <id>`
 */
({ kind: "submodule"; oldCommit: string | null; newCommit: string | null }) & { newBytes?: never; oldBytes?: never } | 
/**  Git cannot read a blob of the file, as in a partial or a shallow clone */
({ kind: "missing" }) & { newBytes?: never; newCommit?: never; oldBytes?: never; oldCommit?: never };

/**  A changed file before its content: the first event of `get_file_diffs` lists them */
export type DiffFileHeader = {
	path: string,
	/**  The path before a rename or copy */
	oldPath: string | null,
	status: FileStatus,
	/**  The blob id of the old text; `None` for an added file and a submodule, whose commits are in its content */
	oldId: string | null,
	/**
	 *  The blob id of the new text; `None` for a deleted file and a submodule. A file of the working tree has the id
	 *  that git would give its bytes (`git hash-object --no-filters`).
	 */
	newId: string | null,
};

/**  The commits a review compares: the old side (the parent, the base of a range) and the new one */
export type DiffRevisions = {
	old: string | null,
	new: string | null,
};

/**  A side of a diff */
export type DiffSide = "old" | "new";

/**  What a diff compares */
export type DiffSource = 
/**  A commit with its first parent */
{ kind: "commit"; id: string } | 
/**  Two commits, as `git diff base head` */
{ kind: "range"; base: string; head: string } | 
/**  The working tree with `HEAD`: staged, unstaged and untracked files */
{ kind: "uncommitted" };

/**  Summary of how two branches have diverged from their common ancestor. */
export type DivergenceSummary = {
	commitsAheadInSource: number,
	commitsAheadInTarget: number,
	commonAncestorDistance: number,
};

/**  A commit of the remote branch whose content the local branch lacks: a push drops it */
export type DroppedCommit = {
	id: string,
	subject: string,
	/**  The author's name */
	author: string,
	authorEmail: string,
	/**  Unix timestamp */
	authorTime: number,
};

/**  An effect of a plan and how it went */
export type EffectRecord = {
	effect: PlannedEffect,
	status: EffectStatus,
	/**
	 *  Of a push that ran: the remote status of each of its `branches`, in their order, as the push found it: the one the
	 *  session showed when it was planned (of Push Up to Here the part up to its commit), or the one after the fetch of a
	 *  refused first push that it went over once more; of a push refused because the remote moved, what the remote has
	 *  now; `None` for a branch whose status the session did not know. The toast of the push and its Activity entry say
	 *  what it did from it (`describePush`); empty for any other effect, and for a push that did not run
	 */
	remote?: (RemoteStatusUpdate | null)[],
};

/**
 *  How an effect went. The first one that fails stops the operation: the effects after it are skipped, and none of the
 *  effects before it is undone
 */
export type EffectStatus = { kind: "done" } | { kind: "failed"; error: ApiError } | 
/**  The answer was lost after the request went out: whether it happened is not known */
{ kind: "unknown" } | 
/**  Not made: an effect before it failed (`reason` `None`), or the facts changed before it (`plan_changed`) */
{ kind: "skipped"; reason: ApiError | null };

/**  Whether the last line of each text is empty and does not count */
export type EmptyLastLine = {
	old: boolean,
	new: boolean,
};

/**  A stable error code. Agents branch on the code and the exit code, never on the message */
export type ErrorCode = 
/**  The arguments don't parse */
"invalid_arguments" | 
/**  `-C` (or the current directory) is not inside a git working tree */
"not_a_repository" | 
/**  No branch prefix from `--prefix`, the repository's `branchdeck.branchPrefix`, the app setting or the global one */
"no_branch_prefix" | 
/**  `--branch` names no current group */
"unknown_branch" | 
/**  No `@{u}`, `<remote>/master`, `<remote>/main` or local `master`/`main` to compare against */
"no_baseline" | 
/**  A plan doesn't apply to the commits ahead of the baseline */
"invalid_plan" | 
/**  A commit of the request is not ahead of the baseline */
"not_ahead_of_baseline" | 
/**
 *  `bd safe-push --whole-stack`: a commit of the stack branch conflicts with the commits of the stack before it
 *  (`commits`, `paths`), though each branch builds: nothing was pushed or started; land the stack in pieces
 */
"stack_conflict" | 
/**
 *  `bd safe-push --whole-stack`: the stack branch is not the build of the stack's commits: a branch of it is blocked or
 *  failed, or the ref is stale (another process moved it); `bd sync` says why. Nothing was pushed or started
 */
"stack_not_built" | 
/**
 *  `bd safe-push`: Patronus can't rebase what the robot lands onto the newest target: a commit (`commits`) conflicts
 *  in files (`paths`) that the target changed after the base of the branch. Nothing was pushed or started; `bd update`
 *  resolves it locally, then start again
 */
"target_conflict" | 
/**
 *  `bd move-hunk`: the change doesn't apply to a commit between the two, which changes the same lines or lacks the
 *  file; `commits` and `paths` name it. Nothing was written: move it by hand, or not at all
 */
"hunk_conflict" | 
/**  `bd move-hunk --block` names a block the file in the commit doesn't have now; `blocks` are the ids it has */
"block_not_found" | 
/**  HEAD moved since the caller read it; read again and retry */
"head_moved" | 
/**  The issue groups (`refs/branch-deck/issue-groups`) changed since the caller read them; read again and retry */
"groups_moved" | 
/**  The stack parents (`refs/branch-deck/stack-parents`) changed since the caller read them; read again and retry */
"stacks_moved" | 
/**  The parked branches (`refs/branch-deck/parked`) changed since the caller read them; read again and retry */
"parked_moved" | 
/**
 *  The app's sync of a session whose branch prefix the git config no longer names (a `git config` meanwhile): nothing
 *  was built; resolve the prefix again and sync the session under it. `bd` resolves the prefix once per command and
 *  never answers it
 */
"prefix_changed" | 
/**
 *  An operation of the remote was prepared over facts that changed before its first effect (a rewrite of another
 *  session, a pull request, a robot, a remote branch): its plan is another one now, and nothing was done. Read the
 *  plan again (`bd safe-push --check`), then retry
 */
"plan_changed" | 
/**  `bd unpark`: the branch is not parked */
"not_parked" | 
/**
 *  `bd unapply`: the virtual branch is not the copies of its commits now (a conflict, no sync since a new commit):
 *  a commit would leave HEAD without a copy. `bd sync` says why; fix the conflict, then unapply. Nothing was changed
 */
"branch_not_built" | 
/**  `bd unapply`: a worktree has the virtual branch checked out (the message names it); nothing was changed */
"branch_checked_out" | 
/**
 *  `bd unapply`: a later commit depends on the changes of a commit of the branch, or the range holds a merge; nothing
 *  was changed. Move that commit into the branch first (`bd group`), or leave the branch applied
 */
"drop_conflict" | 
/**
 *  `bd squash` and `bd fold`: a squashed commit and a commit in between or after it change the same lines
 *  (`commits`, `paths` when a merge named them); nothing was changed. The user decides: squash other commits, or
 *  leave them as they are
 */
"squash_conflict" | 
/**
 *  `bd squash` and `bd fold`: the squashed commit would have no changes, or a later commit would become empty
 *  (`commits`); nothing was changed
 */
"squash_empty" | 
/**
 *  `bd reapply`: a commit of the unapplied branch conflicts with HEAD (`commits`, `paths`); nothing was changed. The
 *  user decides: resolve it in the branch elsewhere, or leave it unapplied
 */
"reapply_conflict" | 
/**
 *  `bd reapply`: HEAD has every commit of the unapplied branch already, or the branch has no common history with the
 *  baseline; nothing was changed
 */
"nothing_to_reapply" | 
/**
 *  `bd push` and `bd safe-push` of a branch that is unapplied (`unapplied` of `bd status`): its commits are not in
 *  HEAD, it lands nothing; `bd push --unapplied <name>` keeps a copy on the remote. Nothing was pushed or started
 */
"unapplied" | 
/**
 *  `bd push` and `bd safe-push`: the branch is parked, or built on a parked branch, or the whole stack holds one: its
 *  commits stay local until the user unparks it (`bd unpark`, never on an agent's own). Nothing was pushed or started
 */
"parked" | 
/**
 *  The remote branch is not where the lease expects it; bd fetched it, `branches` says what it has now. Not retryable:
 *  a push again (with --force) would drop what the remote has now; show `dropped_commits` to the user first
 */
"lease_rejected" | 
/**  Another git process holds a lock; retry */
"locked" | 
/**
 *  An operation of another process (the app, another `bd`) runs what this one needs: the same subject, a branch it
 *  lands or pushes, a robot, a field of a pull request (`holder` names it, from the operations registry of the
 *  repository). Nothing was done; retry when it is done
 */
"busy" | 
/**  A rebase, merge, cherry-pick or revert is in progress */
"operation_in_progress" | 
/**  HEAD is detached */
"detached_head" | 
/**
 *  `bd undo` of a rewrite, an update or a pick the branch (or the issue groups, the stack parents) moved on from: a
 *  commit, another rewrite, a switch. The token can never succeed again
 */
"undo_stale" | 
/**
 *  `bd pick --from`: the reflog of the branch has no fork point of the worktree, and their shared history is local:
 *  commits the branch rewrote since would come back. Name the commits: `bd pick <first>^..<last>`
 */
"range_unknown" | 
/**
 *  `bd pick --from`: the worktree stands on a newer baseline than the branch; the branch is updated first
 *  (`bd update`, by the session that owns it)
 */
"source_on_newer_baseline" | 
/**  `bd pick --remote`: the remote branch has no commit the branch lacks; nothing was picked */
"nothing_to_pick" | 
/**
 *  The app's Pick Remote Commits: a commit of the remote branch conflicts with the checked out branch (`details`: the
 *  commit and its files); nothing was picked
 */
"pick_conflict" | 
/**
 *  `bd lease pick`: the checkout the lease was cut from has another branch checked out than at the get; nothing was
 *  changed. Ask the user: they switched it, and the pick waits until the branch is back
 */
"home_branch_switched" | 
/**  `bd lease pick`: the lease was cut from a detached HEAD, so no branch is named to land on */
"no_home_branch" | 
/**
 *  `bd lease pick` in a repository whose `.branchdeck.toml` sets `pick_requires_check`: no green build or test
 *  recorded the tree of the lease's HEAD (`bd-checks.jsonl` of its git dir); nothing landed. Build and test that
 *  tree, then pick again
 */
"unchecked_tree" | 
/**
 *  `bd update` in a lease of the pool: the lease follows the branch it was cut from, not the baseline; `bd lease
 *  pick` lands its commits there and moves it onto the tip, and the owner of the shared checkout updates that branch
 */
"lease_follows_home" | 
/**
 *  Uncommitted, staged or untracked files sit on paths `bd update`, `bd pick` (or their undo) writes; `paths` lists
 *  them. Nothing was changed; never stash them, ask the user
 */
"uncommitted_overlap" | 
/**  `bd update --continue` or `--abort` without a resolve session of this worktree */
"no_session" | 
/**  `--continue --round <n>` names another round than the open one: `bd update` prints the open round */
"round_moved" | 
/**
 *  The resolve session can't continue: the branch was rewritten, HEAD left the branch, or the session belongs to
 *  another worktree; `bd update --abort` removes it
 */
"session_stale" | 
/**
 *  The conflict of a round is of a type bd can't resolve (binary, file/directory, rename, mode, submodule, symlink);
 *  `paths` lists the files
 */
"unsupported_conflict" | 
/**  Conflict markers are left in the `edit` copies of `paths` */
"unresolved_markers" | 
/**  The `edit` copies of `paths` changed outside their conflict blocks */
"resolution_outside_conflict" | 
/**  The files of `paths` have no resolution: no edited `edit` copy, no `--take`, no `--delete` */
"missing_resolution" | 
/**
 *  The resolution leaves the round's commit without changes: ask the user, then `--allow-empty` or `--drop-empty`;
 *  `--landed` for a commit whose twin the baseline has
 */
"empty_resolution" | 
/**  `bd update --continue --landed` on a round whose commit has no twin in the baseline (no `landed_as`) */
"not_landed_round" | 
/**
 *  `bd update --continue --landed` without `--user` on a round whose commit changes lines that its twin in the
 *  baseline lacks (`landed_as.local_only`): a drop loses them, so the user decides
 */
"landed_differs" | 
/**
 *  `bd update --continue --landed` on a round whose commit still changes files with `onto` for every conflicting
 *  file: `paths` lists them
 */
"landed_not_empty" | 
/**  The branch of a resolve session moved, but the files did not follow and bd can't finish it: show the user */
"finish_pending" | 
/**
 *  A branch can't be pushed: not synced, or behind its remote branch without --force; or the remote refused the push
 *  with every lease holding (a hook, a protected branch, a pack too large). Nothing was pushed
 */
"push_refused" | 
/**
 *  The files the push would add exceed the push size limit (`branchdeck.pushSizeLimit`, 50 MiB unless set): mostly
 *  build output committed by mistake. Nothing was pushed, the remote not asked; the message names the directory that
 *  holds most of it and the largest files, `paths` lists them. Show the user: the files leave the commits, or the
 *  user raises the limit
 */
"push_too_large" | 
/**  No remote to push to */
"no_remote" | 
/**  `bd install` can't write the symlink or a skill, e.g. a file that is not a symlink is in the way */
"install_refused" | 
/**
 *  `bd safe-push`: the code owners haven't approved the branch, and a Safe Push fails without their approvals; nothing
 *  was pushed or started. `review` lists the groups, their reviewers and files, and the merge request; ask the user
 */
"approvals_missing" | 
/**
 *  `bd safe-push`: the push of new commits into the pull request the robot starts from dismisses its approvals, which
 *  Patronus counts (the rules of the target dismiss stale reviews on push): the robot would start without them and
 *  fail; nothing was pushed or started. Push first (`bd push <branch>`), then ask for the review again
 *  (`bd request-review <branch>`)
 */
"push_dismisses_approvals" | 
/**
 *  `bd safe-push`: GitHub didn't answer the rules of the target (no token, no access, an error) for a push of new
 *  commits into a pull request someone approved: the push may dismiss the approvals Patronus counts; nothing was
 *  pushed or started. Ask the user; `--allow-unknown-rules` starts anyway
 */
"rules_unknown" | 
/**
 *  `bd safe-push`: Patronus couldn't answer the code-owner review of the Safe Push (its pre-check failed): whether the
 *  approvals count is not known, never "approved"; nothing was pushed or started. Ask the user;
 *  `--allow-unknown-review` starts anyway, and the robot checks the approvals when it starts
 */
"review_unknown" | 
/**
 *  `bd safe-push`: the open pull request of the branch goes into another base than the target (a release branch), and
 *  Patronus merges a pull request into its base: its approvals count for no Safe Push into the target; nothing was
 *  pushed or started. Retarget it on GitHub once the user approves; `--without-approvals` starts through the API
 */
"pull_request_other_base" | 
/**
 *  `bd safe-push`: a robot runs on the last commit of the branch, on a branch it is built on, or on a branch built on
 *  it; or a Safe Push of an older commit runs, which the push would fail (`--cancel-running`). `bd push`: a Safe Push
 *  runs on the branch or lands it with a branch built on it: a push won't land (`--restart-running`)
 */
"robot_running" | 
/**
 *  `bd push` and `bd safe-push`: a merged Safe Push landed all of the branch (its own, one of a branch built on it, or
 *  of the whole stack), or every branch of the whole stack: its commits are in the target until the update archives
 *  it, a push or a robot would land nothing. `bd status` names who landed it (`landed_by`); `bd update` archives it
 */
"landed" | 
/**
 *  `bd safe-push`: the branch, or a branch it is built on, removes a declaration that its tree still uses, and a
 *  commit of another branch changes the use (`bd check` names it); the build would fail. `--allow-dangling` starts
 *  anyway
 */
"dangling_reference" | 
/**
 *  `bd safe-push`: a commit of what the robot lands uses a name that a commit of another branch adds, which no merged
 *  Safe Push landed (`bd check` names it in `missing_declarations`); git merges it, the build would fail. Stack the root
 *  of what lands on that branch, or move the commit; `--allow-missing` starts anyway
 */
"missing_declaration" | 
/**  `bd safe-push`: the repository is not on Space, or the baseline is not a branch of `origin` */
"not_on_space" | 
/**
 *  `bd safe-push`: no Space token for Patronus, it expired, or Patronus rejected it; the user runs `./safePush.cmd`
 *  once
 */
"not_logged_in" | 
/**
 *  `bd safe-push`: Patronus can't start the robot: the target is not protected, the pull request is a draft, or the
 *  `/patronus` comment was rejected
 */
"patronus_refused" | 
/**
 *  `bd land`: the token may not push into the repository of the target (`viewerPermission` below write): nothing was
 *  pushed; someone with write access lands it
 */
"no_write_access" | 
/**
 *  `bd land`: the rules of the target take a change only through a pull request, and the user may not bypass them:
 *  nothing was pushed. Land it through its pull request
 */
"baseline_requires_pull_request" | 
/**
 *  `bd land`: the target refuses the push: a rule of it no push of the copy passes (the merge queue, restricted
 *  updates, signed commits), or the server refused it (`[remote rejected]`: a hook, a protected branch; the message
 *  says what it said). Nothing was pushed
 */
"baseline_refused" | 
/**
 *  `bd land`: the target moved since the copy was built on it (the server refused a push that is no fast-forward):
 *  nothing was pushed, the baseline was fetched. `bd update` brings the branch onto it, then `bd land` again builds
 *  the copy anew
 */
"baseline_moved" | 
/**
 *  `bd land`: CI did not pass on the commit the push lands (no open pull request, one that shows another commit, its
 *  checks failing or running, GitHub listing none), or changes are requested on its pull request: a push into the
 *  target runs no CI. Nothing was pushed; ask the user, `--without-checks` pushes once they agree
 */
"checks_not_passed" | 
/**
 *  `bd land`: the route of the repository (`branchdeck.landing`) lands no branch through `bd land` yet. Nothing was
 *  pushed
 */
"landing_route_unsupported" | 
/**
 *  `bd land`: GitHub can't merge the pull request of the branch: a merge would conflict, the base requires its head to
 *  be up to date (`bd update`, then `bd push`), or GitHub refused the merge (the message says what it said). Nothing
 *  was merged
 */
"not_mergeable" | 
/**
 *  `bd land`: the rules of the target hold the merge of the pull request back: approvals or required checks are
 *  missing, changes are requested, it is a draft. Nothing was merged; it lands once they come
 */
"merge_blocked" | 
/**
 *  `bd request-review`: the branch has no open pull request, or only a draft; `bd safe-push <branch>
 *  --create-pull-request` opens one, a draft is marked ready for review on GitHub
 */
"no_pull_request" | 
/**  `bd request-review`: a missing group has no code owner with a GitHub login Patronus names; pass `--reviewer` */
"no_reviewer" | 
/**
 *  `bd request-review`: the branch has work its remote branch lacks, which the reviewers would not see; `--push`
 *  pushes it first
 */
"needs_push" | 
/**
 *  `bd request-review`: GitHub asked nobody, it refused every reviewer (the author, a user without access); the
 *  message names each with the reason
 */
"review_refused" | 
/**  `bd lease return`, `bd lease pick`: the worktree holds no lease of the pool, or its get still prepares it */
"no_lease" | 
/**
 *  `bd lease return`: a resolve session of the slot is open; finish it (`bd update --continue`) or close it
 *  (`bd update --abort`) first, so the next lease of the slot never finds it
 */
"resolve_in_progress" | 
/**  `bd lease return --lease-id`: the worktree holds another lease */
"lease_mismatch" | 
/**  `bd lease adopt`: the directory is not the top level of a linked worktree of this repository */
"not_a_slot" | 
/**  `bd lease adopt`: the pool holds the worktree already */
"slot_in_pool" | 
/**
 *  `bd lease return` and `adopt`: a process other than bd and its session has its working directory in the worktree;
 *  `processes` names each with its argv and kind. Nothing was changed
 */
"slot_busy" | 
/**
 *  `bd lease return`: the slot is one of the host slots that `bd-host` keeps for its runs (`n`); `bd-host slots
 *  --local --shrink <n>` gives it back to the pool. Nothing was changed
 */
"host_slot" | 
/**
 *  `bd lease return`: HEAD has commits that no branch, tag or remote branch holds (`commits`): land them first
 *  (`bd pick --from <worktree> --follow` in the shared checkout), or `--confirm-preserved` gives them up
 */
"unlanded_commits" | 
/**
 *  `bd lease return` and `adopt`: the worktree has local changes (`paths`); `bd lease return --confirm-preserved`
 *  discards them, once the user agreed
 */
"dirty_worktree" | 
/**  `bd lease get --branch`: the branch exists */
"branch_exists" | 
/**  `bd lease adopt --move`: the worktree is on another volume than the pool directory; a move would copy every file */
"other_volume" | 
/**  `bd lease get`: the volume of the pool has less free space than `branchdeck.leaseMinFree` or `--min-free` asks */
"low_disk_space" | 
/**
 *  No usable git executable: none found, or one older than the minimum (the message says which and how to install
 *  or upgrade Git)
 */
"git_not_found" | 
/**
 *  Git cannot form the identity of the user (`git var GIT_COMMITTER_IDENT`: `user.name` or `user.email` unset), which
 *  the notes and the rewritten commits are written with: nothing was written; set both, then run again
 */
"no_identity" | 
/**  A git command failed */
"git_error" | 
/**  A network command (fetch, push) failed */
"network_error" | 
/**  A request to Patronus failed; `message` is its answer */
"patronus_error" | 
/**
 *  A failure without a code of its own: `message` is the whole chain of its causes. `bd` prints `git_error` for a
 *  failure of git or IO, as before; the app answers this code
 */
"internal" | 
/**  The user stopped it: a sign-in, a review fetch, a symbol search, a CLI tool's action, a lock wait. Nothing more to show */
"canceled";

/**  The data of an error code, tagged by its kind of data: `{"type": "conflict", "commits": [...], "paths": [...]}` */
export type ErrorDetails = 
/**
 *  The commit that conflicts and its files: `target_conflict`, `hunk_conflict`, `stack_conflict`,
 *  `reapply_conflict`, `drop_conflict`
 */
{ type: "conflict"; commits: string[]; paths: string[] } | 
/**
 *  The files the error is about, relative to the repository: the local files of `uncommitted_overlap`; the directory
 *  that holds most of a `push_too_large` push (`dir/`) and its largest files
 */
{ type: "paths"; paths: string[] } | 
/**  The full names of the branches the error is about: the rejected ones of `lease_rejected` */
{ type: "branches"; branches: string[] } | 
/**  The ids of the blocks the file has now: `block_not_found` */
{ type: "blocks"; blocks: string[] } | 
/**  Who holds the repository lock: `locked`; `None` when the holder wrote no record */
{ type: "locked"; holder: LockHolderInfo | null } | 
/**
 *  The operation of another process that runs what this one needs: `busy`; `None` when the registry is of another
 *  Branch Deck (another schema), whose operations can't be read
 */
{ type: "busy"; holder: OperationHolder | null } | 
/**  What the landing gate refuses of a start, each with its fix: `missing_declaration`, `dangling_reference` */
{ type: "landing"; refusals: LandingRefusal[] } | 
/**
 *  The prefix to suggest where none names the branches (`no_branch_prefix` of the app): the local part of the
 *  committer email of git, without a `+tag`, as a branch name; empty when git names no email
 */
{ type: "prefixSuggestion"; prefix: string };

/**  Everyone else as the median person: the median of each person's value, of the people with at least `MIN_MERGES` */
export type EveryoneDelivery = {
	people: number,
	robots_per_merge: number | null,
	/**  Seconds */
	merge_time: number,
};

/**
 *  What a window asks to run (`execute`): the intent, the fingerprint of the plan it showed, and the confirmations the
 *  user accepted of it; the plan is prepared again and runs only on that fingerprint with every confirmation of it
 *  accepted
 */
export type ExecuteParams = {
	repositoryPath: string,
	intent: Intent,
	fingerprint: Fingerprint,
	accepted?: Confirmation[],
};

/**
 *  A fact of a session that a service or a computation answers (docs/design/rust-domain-authority.md, "Факты"): the
 *  value of the last answer, how it stands now, the number of the observation that answered it (`seq`, from the one
 *  counter of the session: an answer applies only when its observation is newer) and when it answered (Unix seconds).
 *  `value` is `None` until the first answer
 */
export type Fact<T> = {
	value: T | null,
	state: FactState,
	seq: number,
	observedAt: number,
};

/**  A family of the facts of a session, which a window asks to read again (`RefreshFactsParams`) */
export type FactFamily = 
/**  The user's robots of Patronus (`FactsView::robots`) */
"robots" | 
/**
 *  Why the failed robots of the table failed (`RobotsView::needs_review`): Check Approvals Again asks those Patronus
 *  didn't give again; their reads come as patches, the refresh answers at once
 */
"robotProblems" | 
/**  The GitHub pull requests of the branches and whole stacks (`FactsView::pull_requests`) */
"pullRequests" | 
/**  The rules of the bases of the approved pull requests (`FactsView::rules`): those GitHub didn't give are asked again */
"branchRules" | 
/**
 *  The merge profiles of the target of the baseline (`FactsView::profiles`), asked when unknown, after a failure and
 *  a minute after the last read
 */
"profiles" | 
/**
 *  The review readiness of a subject (`FactsView::readiness`): Check Approvals Again (`Manual` with the subject) asks
 *  Patronus again instead of the kept answer; the answer is the version after its patch
 */
"readiness" | 
/**
 *  The pull requests of others that wait for the user's review (`FactsView::review_requests`): the refresh button
 *  asks them (`Manual`); a request opened on GitHub, where the user may answer it, makes the next focus ask at once
 *  (`AfterWrite`, answered at once)
 */
"reviewRequests" | 
/**
 *  The sign-ins of the app's accounts (`FactsView::auth`): read when a window opens the session, on a focus by the
 *  rule of the lists, and at once after a sign-in or a sign-out of any window (`AfterWrite`, which the host asks of
 *  every session)
 */
"auth";

/**  Why a window asks a fact again */
export type FactRefreshReason = 
/**  The refresh button: always asks, the robots of the full window */
"manual" | 
/**
 *  An action of the window changed the remote or needs the fact now: the robot a `/patronus` comment started, a
 *  merge Patronus closed a pull request of, a start that reads the rules and the profiles, a form that opens; asks
 *  when the rules of the family say so for a write (`domain_policy::refresh`), and once more after a read in flight
 */
"afterWrite";

/**
 *  How a fact stands. A fact without an answer is never "no": a read that fails is `Unavailable` with its reason, never
 *  an empty value, and never a `Loading` that lasts
 */
export type FactState = 
/**  No answer yet: from the open of the session (or a change of what it is of) until the first one */
{ kind: "loading" } | 
/**  The value is the answer of the newest observation */
{ kind: "fresh" } | 
/**
 *  The value is an earlier answer: the newest read failed (`reason`), or what the fact is of changed and it is being
 *  read or computed again (`None`); nothing waits for it
 */
{ kind: "stale"; reason?: ApiError | null } | 
/**  No answer: the read failed before any answer came */
{ kind: "unavailable"; reason: ApiError } | 
/**  Nothing asks for it (no window demands it) */
{ kind: "unknown" } | 
/**
 *  The value is what the frame of an earlier run of the app saved (the warm start): no observation of this process
 *  answered it yet. The rules read it as a value (a step and a node show), a start waits for a fresh answer as it does
 *  while the fact loads, a remote action is `ActionBlocker::Cached`, and its first fresh answer is no news
 */
{ kind: "cached" };

/**  A fact a start waits for: no answer yet, or `failed` with why the read failed; never read as "no" */
export type FactWait = {
	fact: LandFact,
	failed: ApiError | null,
};

/**  The parts of the facts that changed */
export type FactsChanges = {
	robots?: RobotsChange | null,
	pullRequests?: PullRequestsChange | null,
	/**  All the rules, when one of them changed: a handful of bases */
	rules?: { [key in string]: Fact<BranchRules> } | null,
	profiles?: Fact<PatronusStartOptions> | null,
	/**  The readiness of the subjects that changed, and the subjects that went */
	readiness?: { [key in string]: Fact<SubjectReadiness> },
	removedReadiness?: string[],
	/**  The details of the robots that changed, and the robots no window demands any more */
	robotDetails?: { [key in string]: Fact<PatronusRobotDetails> },
	removedRobotDetails?: string[],
	/**  The whole part when it changed: at most 50 requests */
	reviewRequests?: ReviewRequestsView | null,
	auth?: Fact<AuthStatus> | null,
};

/**
 *  The facts of the remote services a session keeps, each with how it stands (docs/design/rust-domain-authority.md,
 *  "Факты")
 */
export type FactsView = {
	robots: RobotsView,
	pullRequests: PullRequestsView,
	/**
	 *  By branch, the rules of the bases of the open pull requests someone approved: what a push of new commits does to
	 *  the approvals; a base the session has not read yet has none
	 */
	rules: { [key in string]: Fact<BranchRules> },
	/**
	 *  The merge profiles of the target the baseline pushes to (`targetBranch`), without the default of the last robot
	 *  (the page's until the policy moves into Rust): `Unknown` until a start or its popover asks for them
	 */
	profiles: Fact<PatronusStartOptions>,
	/**
	 *  By subject (a branch, `stack:<root>`), the code-owner review a Safe Push would meet: `Loading` until its first
	 *  answer, `Stale` while it is asked again for other inputs (another tip, start or reviews, Check Approvals Again),
	 *  `Unavailable` when it can't be asked (Patronus not available, a read that failed); a subject nothing asked has none
	 */
	readiness: { [key in string]: Fact<SubjectReadiness> },
	/**
	 *  By robot id, the details of the robots a window shows them of (`Demand::robot_details`: the robot popover, a row of
	 *  the landing overview, a toast that names the failed checks): the checks, the problems, the merge profile and, of a
	 *  running robot, the estimate of the CI; `Loading` until the first answer, read again when the robot's status
	 *  changes and every `RUNNING_DETAILS_REFRESH` while it runs; a robot no window demands any more has none
	 */
	robotDetails: { [key in string]: Fact<PatronusRobotDetails> },
	reviewRequests: ReviewRequestsView,
	/**
	 *  The sign-ins of the app's accounts and where their tokens come from (`remote_facts::sign_in`): one status of the
	 *  app, which every session reads by its rule (`domain_policy::refresh::auth_due`)
	 */
	auth: Fact<AuthStatus>,
};

/**  A failed build of the dependency chain of a check (never a composite one) */
export type FailedBuild = {
	/**  The build configuration name, e.g. "Compile" */
	name: string,
	/**  The full project name, e.g. "IntelliJ / Tests" */
	project: string | null,
	buildId: string,
	buildUrl: string | null,
	failedToStart: boolean,
	problems: BuildProblem[],
	failedTests: FailedTest[],
	/**
	 *  The last messages of the build log, through the `teamcity` CLI; null without it, or for a build that failed only
	 *  on tests
	 */
	logTail: string | null,
};

/**  A failed check, by its last attempt */
export type FailedCheck = {
	/**  The profile name of the check, else its build configuration name, e.g. "Fast Tests" */
	name: string,
	/**  The `TeamCity` build configuration, e.g. `BazelCommunityBuild_Aggregator` */
	buildConfigurationId: string | null,
	/**  The number of the attempt, from 1 */
	attempt: number,
	attemptLimit: number | null,
	/**  The `TeamCity` build of the attempt (the build id, not the build number) */
	buildId: string,
	buildUrl: string | null,
	failedTests: number | null,
	failedBuilds: number | null,
	failedToStart: number | null,
	/**  Still running: the attempt has a failed build, others may follow */
	running: boolean,
};

export type FailedTest = {
	/**  The full name, e.g. `com.intellij.FooTest.testBar` */
	name: string,
	url: string | null,
	/**  The failure message and stack trace, cut to the limit; null beyond the number of messages read */
	message: string | null,
	/**
	 *  The test failed in an earlier build than this one (`TeamCity`'s `firstFailed`): likely not caused by the branch;
	 *  null when unknown
	 */
	firstFailedBefore: boolean | null,
};

/**  Why the user's robots of the runs window failed */
export type FailureCauses = {
	/**  Failed robots of the runs window */
	failed: number,
	/**  Of them, those whose checks were read */
	read: number,
	/**  By kind, the most first */
	kinds: KindCount[],
	/**  The checks that failed the most robots, at most 10 */
	checks: CheckCount[],
	/**  The checks that passed only on a later attempt, the most first, at most 10 */
	flaky: FlakyCheck[],
};

/**  The fastest start hours of everyone else's merges against the slowest one, to say when to start a robot */
export type FastestHours = {
	/**  The first local hour of the longest run of the fastest hours (`StartHour::level` 0) */
	start: number,
	/**  The hour after its last one */
	end: number,
	/**  The median of everyone else's merges that started in them, seconds */
	median: number,
	/**  The hour of the slowest median */
	slowest: number,
	slowest_median: number,
};

/**  What a fetch of the baseline answered */
export type FetchedBaseline = {
	/**  The fetched baseline as it is shown, e.g. `origin/master` */
	upstream: string,
	/**  When the fetch ended (Unix seconds) */
	fetchedAt: number,
	/**
	 *  How much it received, as git prints it ("5.79 MiB"); none when git reported no amount (nothing new, or the result
	 *  of another fetch of the same tracking ref it waited for)
	 */
	transferred: string | null,
};

/**
 *  What `get_file_diffs` sends through its channel: `files` once, then one `content` for each file, the files in view
 *  first, and a `scopes` after the `content` of a text that the caches did not have
 */
export type FileDiffEvent = 
/**  The changed files in the order of git; `index` of the other events points into this list */
{ kind: "files"; files: DiffFileHeader[] } | 
/**
 *  The content of a file. A `TextDiff` that the caches did not have comes with empty scopes, which a `scopes` event
 *  of the same file fills later: the parse costs more than the comparison
 */
{ kind: "content"; index: number; content: DiffContent } | 
/**  The scopes of the text of a file, for the labels of its hunks */
{ kind: "scopes"; index: number; oldScopes: Scope[]; newScopes: Scope[] };

/**
 *  What `get_file_merges` sends through its channel: `files` once, then one `content` for each file, the files in view
 *  first, and a `scopes` after the `content` of a text merge that the caches did not have
 */
export type FileMergeEvent = 
/**  The conflicting files in the order of git; `index` of the other events points into this list */
{ kind: "files"; files: FileMergeHeader[] } | { kind: "content"; index: number; content: MergeContent } | 
/**  The scopes of the three sides of a text merge */
{ kind: "scopes"; index: number; leftScopes: Scope[]; baseScopes: Scope[]; rightScopes: Scope[] };

/**  A conflicting file before its content: the first event of `get_file_merges` lists them */
export type FileMergeHeader = {
	path: string,
	kind: GitConflictKind,
	/**
	 *  The blob ids of the stages: base (1), left (2, ours, the target) and right (3, theirs, the picked commit); `None`
	 *  for a stage that the path does not have, and for a submodule, whose commits are in its content
	 */
	baseId: string | null,
	leftId: string | null,
	rightId: string | null,
	/**
	 *  The blob of the file in the copy that resolved the conflict by words (`MergeSource::CherryPick::resolved`): what
	 *  the sync committed, which the view shows as the result; `None` without that copy or for a path it lacks
	 */
	resolvedId: string | null,
};

/**  The owner of a path and the rule that names it */
export type FileOwner = {
	path: string,
	owner: string,
	/**  The pattern relative to the repository root, e.g. `plugins/air/**` */
	rule: string,
	/**  The `OWNERSHIP` file of the rule, e.g. `plugins/air/OWNERSHIP` */
	sourceFile: string,
};

/**  How a file changed, from the status letter of `--raw` */
export type FileStatus = "added" | "modified" | "deleted" | "renamed" | "copied" | 
/**  A file became a symlink or a submodule, or the other way round */
"typeChanged";

/**  Whether each text ends with a line end */
export type FinalNewline = {
	old: boolean,
	new: boolean,
};

export type FindConflictFixParams = {
	repositoryPath: string,
};

/**  The parameters of `find_declaration`: a name in a diff of a review and the files of the review (`declarations.rs`) */
export type FindDeclarationParams = {
	repositoryPath: string,
	site: DeclarationSite,
	/**  The changed files of the review, whose sides are searched */
	files: ReviewFileSides[],
	/**  The revisions of the sides, for a declaration outside the review; none for the working tree */
	revisions?: DiffRevisions,
};

/**
 *  The hash of a plan with what it was prepared on (`operations::witness`): the intent and what it decided, the tips of
 *  the refs it moves and the remote branches it leases, the pull requests and robots it reads. Equal only within one
 *  process
 */
export type Fingerprint = string;

/**
 *  The first local commit whose replay onto the upstream conflicts: the merge of its change onto the upstream with the
 *  local commits before it
 */
export type FirstConflict = {
	/**  The commit; its `files` are `files` */
	commit: UpdateCommit,
	/**  The files whose merge conflicts, at most the first `MAX_ATTRIBUTED_FILES` */
	files: string[],
	/**  All files whose merge conflicts: a monorepo commit can conflict in thousands */
	fileCount: number,
	/**
	 *  The upstream commits since the merge base that changed `files`, oldest first, at most the newest
	 *  `MAX_UPSTREAM_COMMITS`
	 */
	upstreamCommits: UpdateCommit[],
};

/**  Steps that belong together: they share a branch, and their plan alone has the result */
export type FixComponent = {
	steps: FixStep[],
	plan: RegroupPlan,
	/**  The branches that conflicted (or had a dangling reference) and apply cleanly afterwards */
	fixed: string[],
	/**  The branches blocked by a parent before that apply cleanly afterwards */
	unblocked: string[],
	/**  The branches that have no commits afterwards */
	emptied: string[],
	/**  The branches stacked on an emptied one: built on its nearest ancestor with commits */
	orphanedChildren: string[],
	/**  The subjects the plan rewrites */
	rewritten: number,
};

export type FixStep = {
	kind: FixStepKind,
	/**  Oldest first; empty for a restack */
	commits: string[],
	/**  The branches the commits leave, an unassigned commit leaves none; the old parent of a restack */
	from: string[],
	to: string,
	/**  The branch whose conflict or dangling reference the step is for */
	fixes: string,
};

export type FixStepKind = 
/**  `commits` leave the conflicting branch for `to`, the branch whose stack has what they need */
"move" | 
/**  `commits`, what the branch `to` needs, come into it from `from` */
"pullIn" | 
/**  The branch `fixes` is stacked on `to` */
"restack";

/**  How a commit is squashed into its target; the first marker of the subject decides (`fixup! squash! X` is a fixup) */
export type FixupKind = 
/**  `fixup!`: the target keeps its message */
"Fixup" | 
/**  `squash!`: the body of the squash commit is appended to the target's message */
"Squash" | 
/**  `amend!`: the body of the amend commit replaces the target's message */
"Amend";

export type FlakyCheck = {
	name: string,
	/**  Passed on attempt 2 or later */
	count: number,
	/**  Passed or failed */
	runs: number,
	/**  `count / runs`; null below `MIN_FLAKY_RUNS` runs */
	share: number | null,
	/**  The page of the newest robot it passed on a retry in */
	robot_url: string,
};

/**
 *  A branch whose ref git cannot hold beside another one: `<prefix>/virtual/auth/login` needs a directory where
 *  `<prefix>/virtual/auth` is a file, so a sync fails on it
 */
export type FlatNameClash = {
	/**  The flat name, `auth/login` */
	branch: string,
	/**  The branch whose name is a directory of it, `auth` */
	beside: string,
};

/**  The declarations a name may mean, the most likely first */
export type FoundDeclarations = {
	name: string,
	targets: DeclarationTarget[],
	/**  Why the index of the repository did not answer, when it was asked */
	indexError: string | null,
};

/**
 *  The usages of a name (`usages.rs`): those of the file of the name, of the other files of the review, then those
 *  outside the review that the index knows
 */
export type FoundUsages = {
	name: string,
	usages: UsageTarget[],
	/**  The index knows more usages outside the review than it answered */
	moreOutside: boolean,
	/**  Why the index of the repository did not answer, when it was asked */
	indexError: string | null,
};

